import{_ as i,o as t,c as e,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS G/H (Day 2) - RBD: Database Performance","description":"","frontmatter":{"title":"CDS G/H (Day 2) - RBD: Database Performance","date":"2014-06-26T00:00:00.000Z","updated":"2014-06-26T00:00:00.000Z","tags":["Ceph","RBD","Database Performance","CephFS","Benchmarking"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_2_-_RBD_-_Database_Performance.md","filePath":"posts/2014/CDS_G_H_Day_2_-_RBD_-_Database_Performance.md","lastUpdated":1780459816000}'),r={name:"posts/2014/CDS_G_H_Day_2_-_RBD_-_Database_Performance.md"};function s(o,l,n,_,p,D){return t(),e("div",null,[...l[0]||(l[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： JYG, MT Wong, Luke, inkten, sam, josh, 等</p><p><strong>会议主题</strong>： Ceph数据库性能优化及测试方案</p><p><strong>会议内容</strong>：</p><p><strong>1. 会议背景</strong></p><ul><li>探讨在Ceph上运行数据库，特别是RBD上的数据库性能优化。</li><li>目标是实现跨广域网络的数据库运行，而非多站点复制。</li></ul><p><strong>2. 讨论议题</strong></p><ul><li><strong>数据库性能问题</strong>： <ul><li>使用Ceph作为后端存储的数据库（如PostgreSQL、MySQL等）性能不如预期。</li><li>可能的原因包括： <ul><li>RBD的striping策略导致小写入操作堆积在单个对象上，影响性能。</li><li>数据库的写前日志（WAL）可能导致性能瓶颈。</li><li>网络延迟和复制开销。</li></ul></li></ul></li><li><strong>优化方案</strong>： <ul><li>调整RBD的striping策略，优化小写入操作的处理。</li><li>将WAL存储在独立的设备上，例如SSD。</li><li>使用RBD缓存来提高性能。</li><li>调整Ceph和数据库的配置参数。</li><li>使用SSD作为OSD的存储介质。</li></ul></li><li><strong>测试方案</strong>： <ul><li>使用firefly进行性能测试，对比不同配置下的性能表现。</li><li>使用block trace和sequencer等工具进行性能分析。</li><li>与社区分享测试结果和最佳实践。</li></ul></li></ul><p><strong>3. 决定事项</strong></p><ul><li>成立一个工作组，负责Ceph数据库性能优化和测试。</li><li>工作组将制定详细的测试方案，并开始进行测试。</li><li>工作组将定期分享测试结果和最佳实践。</li></ul><p><strong>4. 后续行动计划</strong></p><ul><li>工作组将制定详细的测试方案，包括测试环境、测试用例、测试工具等。</li><li>工作组将开始进行测试，并记录测试结果。</li><li>工作组将分析测试结果，并找出性能瓶颈。</li><li>工作组将根据分析结果，提出优化方案。</li><li>工作组将分享测试结果和最佳实践，并与社区进行讨论。</li></ul><p><strong>5. 关键词</strong></p><ul><li>RBD</li><li>PostgreSQL</li><li>MySQL</li><li>WAL</li><li>Striping</li><li>SSD</li><li>Cache</li><li>Performance</li><li>Benchmark</li><li>Test</li><li>Community</li></ul>',16)])])}const u=i(r,[["render",s]]);export{c as __pageData,u as default};
